// Frozen, unsorted input also catches in-place sorting or row mutation.
const rows = Object.freeze([
  { id: 'b', tenant: 'a', createdAt: '2026-01-01', total: 2 },
  { id: 'z', tenant: 'other', createdAt: '2026-01-01', total: 3 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: '10', tenant: 'a', createdAt: '2026-01-01', total: 4 },
  { id: '2', tenant: 'a', createdAt: '2026-01-01', total: 5 },
  { id: 'A', tenant: 'a', createdAt: '2026-01-02', total: 6 }
].map(Object.freeze));
const paginated = new OrderHandler(new OrderRepository(rows));
let cursor;
const ids = [];
do {
  const page = paginated.list({ tenant: 'a', limit: 2, cursor });
  ids.push(...page.items.map(row => row.id));
  if (page.nextCursor !== null) {
    const last = page.items[page.items.length - 1];
    assert.equal(page.nextCursor, last.createdAt + '|' + last.id);
  }
  cursor = page.nextCursor;
} while (cursor !== null);
assert.deepEqual(ids, ['10', '2', 'a', 'b', 'A']);
assert.equal(paginated.list({ tenant: 'a', limit: 5 }).nextCursor, null);
assert.deepEqual(paginated.list({ tenant: 'missing', limit: 1 }), { items: [], nextCursor: null });
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '9999|z' }), { items: [], nextCursor: null });
// Resume by value, not by finding an existing row, even across tenants.
assert.deepEqual(paginated.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|aa' }), {
  items: [rows[0], rows[5]], nextCursor: null
});
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|z' }), {
  items: [rows[5]], nextCursor: null
});
const deleted = new OrderHandler(new OrderRepository(rows.filter(row => row.id !== 'a')));
assert.deepEqual(deleted.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|a' }), {
  items: [rows[0]], nextCursor: '2026-01-01|b'
});
for (const cursor of ['', '|', 'date|', '|id', 'date', 'date|id|extra', null, 42]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit: 1, cursor }), /^Error: invalid request$/);
}
for (const limit of [0, -1, 101, 1.5, NaN, Infinity, '1']) {
  assert.throws(() => paginated.list({ tenant: 'a', limit }), /^Error: invalid request$/);
}
assert.throws(() => paginated.list({ tenant: '', limit: 1 }), /^Error: invalid request$/);
assert.equal(paginated.list({ tenant: 'a', limit: 100 }).items.length, 5);

